from PIL import Image
import json

img = Image.open('/app/figure.jpg')
print(f"Size: {img.size}")
print(f"Mode: {img.mode}")
print(f"Format: {img.format}")

# Check for embedded metadata
if hasattr(img, 'info'):
    for k, v in img.info.items():
        if isinstance(v, (str, bytes)) and len(str(v)) < 500:
            print(f"  Info {k}: {v}")
        else:
            print(f"  Info {k}: (len={len(str(v))})")

# Check exif
from PIL.ExifTags import TAGS
try:
    exif = img._getexif()
    if exif:
        for tag_id, value in exif.items():
            tag_name = TAGS.get(tag_id, tag_id)
            if isinstance(value, str) and len(value) < 200:
                print(f"  EXIF {tag_name}: {value}")
except Exception as e:
    print(f"EXIF error: {e}")

# Try to get image description from EXIF
exif_data = img.getexif()
if exif_data:
    for k, v in exif_data.items():
        if k == 0x010e or k == 0x9286:  # ImageDescription or UserComment
            print(f"Description/Comment: {v}")
PYEOF

